// The GitHub writes of network clients: `curl`, `wget`, `http`, and `xh`.
// A write is a method other than `GET` or `HEAD`, or a body, or a post flag. The reading splits the words of the call and the URL.
// The URL is parsed by its parts: the scheme, the host, and the path. A URL that a shell expands at run time cannot be read, so it is reported as unclear.

import { isDynamic } from "./paths.ts";

/** What a network call does to GitHub. `repos` are the `OWNER/NAME` names in its URLs. */
export type Net = {
  /** The call sends a method or data that changes the server. */
  write: boolean;
  /** The call saves a file, so it also changes a folder. */
  output: boolean;
  repos: string[];
  /** A GitHub URL has no repository in its path, or a URL cannot be read. */
  unclear: boolean;
};

const GH_HOSTS: ReadonlySet<string> = new Set([
  "github.com",
  "api.github.com",
  "uploads.github.com",
]);
const CLIENTS: ReadonlySet<string> = new Set([
  "curl",
  "wget",
  "http",
  "https",
  "xh",
  "xhs",
]);
const SAFE_METHODS: ReadonlySet<string> = new Set(["GET", "HEAD", "OPTIONS"]);

/** The short flags of `curl` that take a value, and the long ones. */
const CURL_SHORT = "AbcCdDeEFHKmoPQrTuUwxXyYzt";
const CURL_LONG: ReadonlySet<string> = new Set([
  "--request",
  "--header",
  "--user",
  "--user-agent",
  "--referer",
  "--cookie",
  "--cookie-jar",
  "--output",
  "--output-dir",
  "--max-time",
  "--connect-timeout",
  "--write-out",
  "--proxy",
  "--cacert",
  "--cert",
  "--key",
  "--retry",
  "--retry-delay",
  "--retry-max-time",
  "--config",
  "--resolve",
  "--dump-header",
  "--range",
  "--limit-rate",
  "--max-redirs",
  "--oauth2-bearer",
  "--url",
  "--upload-file",
  "--form",
  "--form-string",
  "--json",
  "--variable",
  "--proxy-user",
  "--trace",
  "--trace-ascii",
]);
const CURL_OUT_LONG: ReadonlySet<string> = new Set([
  "--output",
  "--remote-name",
  "--remote-name-all",
  "--dump-header",
  "--cookie-jar",
  "--output-dir",
  "--trace",
  "--trace-ascii",
]);
const WGET_SHORT = "OoaePUtTwQiB";
const WGET_LONG: ReadonlySet<string> = new Set([
  "--header",
  "--user-agent",
  "--output-document",
  "--output-file",
  "--append-output",
  "--directory-prefix",
  "--post-data",
  "--post-file",
  "--method",
  "--body-data",
  "--body-file",
  "--referer",
  "--user",
  "--password",
  "--http-user",
  "--http-password",
  "--load-cookies",
  "--save-cookies",
  "--timeout",
  "--tries",
  "--execute",
]);
const HTTP_LONG: ReadonlySet<string> = new Set([
  "--auth",
  "--session",
  "--output",
  "--timeout",
  "--proxy",
  "--verify",
  "--cert",
  "--cert-key",
  "--print",
  "--pretty",
  "--style",
  "--max-redirects",
  "--auth-type",
]);
const HTTP_SHORT = "aosp";

/** The host and the path of `word`, or `undefined` when it is no URL. A word with no scheme counts when it starts with a GitHub host. */
const split = (word: string): { host: string; path: string } | undefined => {
  const m =
    /^(?:[a-z][a-z0-9+.-]*:\/\/)?(?:[^@/]*@)?([^/:?#]*)(?::[^/?#]*)?(\/[^?#]*)?/i.exec(
      word,
    );
  const hasScheme = /^[a-z][a-z0-9+.-]*:\/\//i.test(word);
  if (m === null) return undefined;
  const host = (m[1] ?? "").toLowerCase();
  if (!hasScheme && !GH_HOSTS.has(host) && !isDynamic(host)) return undefined;
  if (!hasScheme && host === "") return undefined;
  return { host, path: m[2] ?? "" };
};

/** Adds the repository of `word` to `net`, or marks `net` unclear. A URL of another host is ignored. */
const addUrl = (net: Net, word: string): void => {
  const u = split(word);
  if (u === undefined) return;
  if (isDynamic(u.host)) {
    net.unclear = true;
    return;
  }
  if (!GH_HOSTS.has(u.host)) return;
  const parts = u.path.split("/").filter((p) => p !== "");
  const named =
    u.host === "github.com"
      ? parts.slice(0, 2)
      : parts[0] === "repos"
        ? parts.slice(1, 3)
        : [];
  if (named.length < 2 || named.some(isDynamic)) {
    net.unclear = true;
    return;
  }
  net.repos.push(`${named[0]}/${named[1]}`);
};

const methodWrites = (method: string): boolean =>
  !SAFE_METHODS.has(method.toUpperCase());

/** Walks the words of a `curl` or `wget` call. `short` and `long` tell which flags take a value. */
const walk = (
  net: Net,
  words: string[],
  short: string,
  long: ReadonlySet<string>,
  wget: boolean,
): void => {
  for (let i = 1; i < words.length; i++) {
    const w = words[i] as string;
    if (w.startsWith("--")) {
      const eq = w.indexOf("=");
      const name = eq < 0 ? w : w.slice(0, eq);
      const value =
        eq >= 0
          ? w.slice(eq + 1)
          : long.has(name)
            ? (words[++i] ?? "")
            : undefined;
      if (name === "--request" || name === "--method") {
        if (methodWrites(value ?? "")) net.write = true;
      } else if (/^--(data|form|upload-file|json|post|body)/.test(name))
        net.write = true;
      if (CURL_OUT_LONG.has(name) && !wget) net.output = true;
      if (value !== undefined && /^--url$/.test(name)) addUrl(net, value);
    } else if (w.startsWith("-") && w.length > 1) {
      for (let c = 1; c < w.length; c++) {
        const ch = w.charAt(c);
        if (!wget && (ch === "O" || ch === "J")) net.output = true;
        if (!short.includes(ch)) continue;
        const value = c + 1 < w.length ? w.slice(c + 1) : (words[++i] ?? "");
        if (ch === "X" && !wget && methodWrites(value)) net.write = true;
        else if (!wget && "dFT".includes(ch)) net.write = true;
        else if (!wget && "oDc".includes(ch)) net.output = true;
        break;
      }
    } else addUrl(net, w);
  }
};

/** Walks the words of an `http` or `xh` call. */
const walkHttp = (net: Net, words: string[]): void => {
  let methodSeen = false;
  let ignoresStdin = false;
  let items = false;
  for (let i = 1; i < words.length; i++) {
    const w = words[i] as string;
    if (w.startsWith("--")) {
      const name = w.includes("=") ? w.slice(0, w.indexOf("=")) : w;
      if (name === "--ignore-stdin" || name === "--offline")
        ignoresStdin = true;
      if (name === "--download" || name === "--output") net.output = true;
      if (HTTP_LONG.has(name) && !w.includes("=")) i++;
    } else if (w.startsWith("-") && w.length > 1) {
      if (w.includes("I")) ignoresStdin = true;
      if (w === "-d" || w === "-o") net.output = true;
      if (w.length === 2 && HTTP_SHORT.includes(w.charAt(1))) i++;
    } else if (!methodSeen && /^[A-Za-z]+$/.test(w) && /^[A-Z]+$/.test(w)) {
      methodSeen = true;
      if (methodWrites(w)) net.write = true;
    } else if (/^[\w.[\]-]+(==|:=@|:=|=@|=|@)/.test(w) && !w.includes("://")) {
      if (!/^[\w.[\]-]+==/.test(w)) items = true;
    } else if (/^[\w-]+:[^/\d]/.test(w) && !w.includes("://")) {
      // A header item such as `Name:value` adds no body.
    } else {
      methodSeen = true;
      addUrl(net, w);
    }
  }
  if (items || !ignoresStdin) net.write = true;
};

/** What the call `words` does to GitHub, or `undefined` when `head` is no network client in the list. */
export const netOf = (head: string, words: string[]): Net | undefined => {
  if (!CLIENTS.has(head)) return undefined;
  const net: Net = { write: false, output: false, repos: [], unclear: false };
  if (head === "curl") walk(net, words, CURL_SHORT, CURL_LONG, false);
  else if (head === "wget") {
    walk(net, words, WGET_SHORT, WGET_LONG, true);
    net.output = true;
  } else walkHttp(net, words);
  return net;
};
